-- Approved, non-sensitive configuration only. Catalog/content inserts preserve
-- later admin edits; versioned quiz definitions refresh their approved JSON.
-- No transactional or fabricated records.

insert into public.package_catalog
  (offer_key, name, build_route, supported_platforms, base_price_usd, level, active, display_order, description, included_capability_keys, limits, support_days, revision_rounds)
values
  ('platform_launch','Launch System','platform',array['systeme_io','gohighlevel'],1500,1,true,10,'Best for one offer, one audience, and one primary conversion action.',array['responsive_build','lead_form','confirmation_page','basic_booking_or_checkout','basic_email_follow_up','basic_analytics'],
   jsonb_build_object('included_features',jsonb_build_array('Strategy and conversion-path planning for one offer','One landing page or compact conversion website of up to five core sections','Responsive desktop, tablet, and mobile setup','One lead form, application form, or inquiry form','One thank-you or confirmation page','One basic booking or checkout connection','One confirmation email and one basic follow-up sequence of up to three emails','Basic tags, contact fields, and simple segmentation','Basic analytics and conversion-event setup','Domain connection guidance','Launch testing and handover')),0,1),
  ('platform_growth','Growth System','platform',array['systeme_io','gohighlevel'],2500,2,true,20,'Best for a connected lead-to-booking, enrollment, or order journey.',array['multi_step_funnel','lead_qualification','booking_or_checkout','crm_pipeline','email_follow_up','basic_onboarding','two_standard_integrations'],
   jsonb_build_object('included_features',jsonb_build_array('Everything in Launch System where applicable','Multi-step funnel or conversion website of up to five primary pages or steps','Lead qualification or application flow','Booking, checkout, enrollment, or deposit connection','CRM pipeline with core stages','Automated confirmation, reminders, and follow-up sequence of up to seven emails or messages','Basic onboarding workflow','Audience or offer segmentation','Up to two standard third-party integrations','Funnel and pipeline testing','Recorded handover or training session')),0,2),
  ('platform_scale','Scale System','platform',array['systeme_io','gohighlevel'],4000,3,true,30,'Best for multiple offers, connected pipelines, and advanced platform-native automation.',array['multiple_offers','advanced_pipeline','conditional_workflows','extended_nurture','platform_onboarding_area','four_standard_integrations','basic_reporting'],
   jsonb_build_object('included_features',jsonb_build_array('Everything in Growth System where applicable','Up to two offers, funnels, or audience paths','Advanced pipeline stages and opportunity automation','Conditional workflows using the selected platform native capabilities','Extended email or SMS nurture of up to twelve messages','Client or student onboarding area using platform-native features where available','Up to four standard integrations','Basic reporting dashboard using available platform data','Team access and permissions supported by the client subscription','End-to-end quality assurance','Training and 30-day post-launch technical support')),30,2),
  ('custom_starter','Custom Starter','custom',array['custom_app'],3000,1,true,40,'Best for a focused minimum viable product with one clear internal or customer-facing workflow.',array['focused_module','single_user_type_auth','core_crud_status_workflow','simple_admin_view','basic_notification'],
   jsonb_build_object('included_features',jsonb_build_array('Discovery session and simplified workflow map','Custom responsive interface for one focused module','Supabase project, database, and basic security setup','Authentication for one primary user type','One core create, view, edit, and status workflow','Simple admin management view','Basic form validation and record search or filtering','One basic notification or confirmation workflow','Deployment and environment configuration','Testing, handover, and 30-day technical support')),30,1),
  ('custom_foundation','Custom Foundation','custom',array['custom_app'],5000,2,true,50,'Best for a production-ready custom app with a connected admin and user experience.',array['admin_and_user_auth','two_core_workflows','admin_dashboard','file_upload','two_standard_integrations','basic_activity_history'],
   jsonb_build_object('included_features',jsonb_build_array('Everything in Custom Starter where applicable','Detailed workflow and data-model planning','Supabase database, authentication, storage, and access policies','Secure authentication for one primary user type plus admin','Up to two connected core workflows','Custom admin dashboard with operational status tracking','File or image upload capability','Expanded search, filtering, and record-management functions','Up to two standard third-party integrations','Basic analytics and activity history','Email notifications or workflow confirmations','Testing, handover, and 30-day technical support')),30,2),
  ('custom_growth','Custom Growth','custom',array['custom_app'],7500,3,true,60,'Best for several connected workflows, portals, roles, and dashboards.',array['three_user_roles','basic_custom_portal_module','custom_dashboard_reporting_module','multiple_workflows','three_standard_integrations','operational_reporting'],
   jsonb_build_object('included_features',jsonb_build_array('Everything in Custom Foundation where applicable','Up to three user roles with permission-based views','Client, student, customer, employee, or partner portal','Multiple connected business workflows','Advanced admin dashboard and status tracking','File upload or document-management capability','Search, filtering, and operational reporting','Up to three standard third-party integrations','Automated notifications and workflow triggers','Audit-friendly activity history for important actions','Supabase row-level security policies for each supported role','Training and 60-day technical support')),60,2),
  ('custom_complete','Complete Custom System','custom',array['custom_app'],10000,4,true,70,'Best for complex operations, multiple departments, inventory, delivery, or specialized business rules.',array['advanced_roles','multiple_portals','custom_approvals','advanced_reporting','complex_business_rules','expanded_integrations'],
   jsonb_build_object('starting_price',true,'requires_scope_review',true,'included_features',jsonb_build_array('Everything in Custom Growth where applicable','Advanced roles and permission structure','Multiple portals or department-specific workspaces','Inventory, production, order, delivery, or resource-management modules as scoped','Custom approvals and multi-stage workflows','Advanced reporting and management dashboards','Complex calculations or business rules','Expanded integration requirements','Data migration plan where required','Advanced Supabase data relationships, storage policies, and server-side functions as required','Security review and extended quality assurance','Phased rollout plan','Training and 90-day technical support')),90,3)
on conflict (offer_key) do nothing;

