  ('standard_third_party_integration','Standard third-party integration','A standard supported third-party integration.',350,'Per integration',array['platform','custom'],array['platform_growth','platform_scale','custom_foundation','custom_growth','custom_complete'],false,true,180),
  ('complex_custom_api_integration','Complex/custom API integration','A complex or custom API integration requiring review.',750,'Per integration after review',array['platform','custom'],'{}',true,true,190),
  ('content_data_migration','Content or data migration','Content or data migration based on volume and cleanup needs.',500,'Based on volume and cleanup',array['platform','custom'],'{}',true,true,200),
  ('additional_revision_round','Additional revision round','One additional revision round.',300,'Per round',array['platform','custom'],'{}',false,true,210)
