-- Approved version-one quiz definitions. These JSON documents are generated
-- from the same reviewed keys, labels, signals, and scoring contract used by
-- the portable Cortex engine. They contain no visitor or transactional data.
with approved_quiz_definitions(audience_key, questions) as (
  values
  ('coaches_educators', $json$[{"key":"q1_goal","prompt":"What result matters most right now?","options":[{"key":"coach_goal_book_calls","label":"Book more discovery or coaching calls.","signals":["booking","lead_generation"]},{"key":"coach_goal_enroll_students","label":"Enroll more students in a course or program.","signals":["enrollment","lead_generation"]},{"key":"coach_goal_sell_digital_offer","label":"Sell a workshop, membership, or digital offer.","signals":["enrollment","checkout"]},{"key":"coach_goal_organized_material_access","label":"Give learners an organized place to access materials.","signals":["course_delivery","onboarding"]}],"selection":"single","scope":"audience","required":true},{"key":"q2_setup","prompt":"How do people currently discover and join your offer?","options":[{"key":"coach_setup_social_dm","label":"Mostly through social media and direct messages.","signals":["lead_generation"]},{"key":"coach_setup_unclear_website","label":"Through a website, but the path is unclear.","signals":["credibility","lead_generation"]},{"key":"coach_setup_funnel_needs_improvement","label":"Through a landing page or funnel that needs improvement.","signals":["lead_generation","follow_up"]},{"key":"coach_setup_disconnected_tools","label":"I have multiple tools, but they are disconnected.","signals":["disconnected_tools"]}],"selection":"single","scope":"audience","required":true},{"key":"q3_blocker","prompt":"Where does the journey usually get stuck?","options":[{"key":"coach_blocker_few_qualified_inquiries","label":"Not enough qualified inquiries.","signals":["lead_generation"]},{"key":"coach_blocker_questions_no_booking","label":"People ask questions but do not book or enroll.","signals":["booking","lead_generation"]},{"key":"coach_blocker_manual_follow_up","label":"Follow-up is inconsistent or manual.","signals":["follow_up"]},{"key":"coach_blocker_disorganized_onboarding","label":"Onboarding and content access are disorganized.","signals":["onboarding","course_delivery"]}],"selection":"single","scope":"audience","required":true},{"key":"q4_capabilities","prompt":"What should the new system handle?","options":[{"key":"coach_capability_offer_page","label":"Offer or program page.","signals":["credibility"]},{"key":"coach_capability_lead_capture","label":"Lead capture.","signals":["lead_generation"]},{"key":"coach_capability_booking","label":"Discovery-call booking.","signals":["booking"]},{"key":"coach_capability_enrollment_payment","label":"Enrollment and payment.","signals":["enrollment","checkout"]},{"key":"coach_capability_email_follow_up","label":"Email follow-up.","signals":["follow_up"]},{"key":"coach_capability_student_onboarding","label":"Student onboarding or portal.","signals":["onboarding","course_delivery"]},{"key":"coach_capability_progress_resources","label":"Progress or resource access.","signals":["course_delivery"]}],"selection":"multiple","scope":"audience","helpText":"Select all that apply.","required":true},{"key":"q5_complexity","prompt":"How complex is your offer setup?","options":[{"key":"coach_complexity_one_offer","label":"One offer and one clear action.","signals":["simple_scope"]},{"key":"coach_complexity_multiple_offers","label":"Multiple offers or audience segments.","signals":["multiple_offers"]},{"key":"coach_complexity_program_delivery","label":"A program with enrollment, onboarding, and content access.","signals":["enrollment","onboarding","course_delivery"]},{"key":"coach_complexity_custom_experience","label":"A custom learning or client experience with integrations.","signals":["portal","integration"]}],"selection":"single","scope":"audience","required":true},{"key":"q6_readiness","prompt":"When do you want to begin?","options":[{"key":"readiness_ready_now","label":"Ready now.","signals":[],"readiness":"ready_now"},{"key":"readiness_within_30_days","label":"Within 30 days.","signals":[],"readiness":"within_30_days"},{"key":"readiness_within_1_2_months","label":"Within 1–2 months.","signals":[],"readiness":"planning_1_2_months"},{"key":"readiness_researching","label":"Researching for later.","signals":[],"readiness":"researching"}],"selection":"single","scope":"universal","required":true},{"key":"q7_platform","prompt":"Do you already have a preferred platform?","options":[{"key":"platform_systeme","label":"Systeme.io.","signals":[],"platformPreference":"systeme_io"},{"key":"platform_gohighlevel","label":"GoHighLevel.","signals":[],"platformPreference":"gohighlevel"},{"key":"platform_custom_app","label":"I want a custom-built app.","signals":[],"platformPreference":"custom_app"},{"key":"platform_recommend","label":"I am not sure—recommend the best fit for me.","signals":[]}],"selection":"single","scope":"universal","required":true},{"key":"q8_support","prompt":"What additional support do you need for this project?","options":[{"key":"support_conversion_copywriting","label":"Conversion copywriting.","signals":["no_system_effect"],"addonKey":"conversion_copywriting"},{"key":"support_image_sourcing","label":"Image sourcing and selection.","signals":["no_system_effect"],"addonKey":"image_sourcing_selection"},{"key":"support_image_editing","label":"Image editing and optimization.","signals":["no_system_effect"],"addonKey":"image_editing_optimization"},{"key":"support_brand_direction","label":"Brand styling or mini visual direction.","signals":["no_system_effect"],"addonKey":"mini_brand_direction"},{"key":"support_additional_pages","label":"Additional pages or funnel steps.","signals":["credibility"],"addonKey":"additional_page_step"},{"key":"support_booking","label":"Appointment booking setup.","signals":["booking"],"addonKey":"advanced_booking_setup"},{"key":"support_checkout","label":"Checkout or payment integration.","signals":["checkout"],"addonKey":"checkout_payment_integration"},{"key":"support_follow_up","label":"Email or SMS follow-up automation.","signals":["follow_up"],"addonKey":"additional_email_automation"},{"key":"support_crm","label":"CRM or pipeline setup.","signals":["pipeline"],"addonKey":"additional_crm_pipeline"},{"key":"support_onboarding","label":"Client/student onboarding.","signals":["onboarding"],"addonKey":"advanced_onboarding_workflow"},{"key":"support_portal","label":"Client/student portal.","signals":["portal"]},{"key":"support_order_management","label":"Order-management workflow.","signals":["custom_orders","order_tracking"],"addonKey":"custom_order_management_module"},{"key":"support_dashboard","label":"Dashboard or reporting.","signals":["dashboard"],"addonKey":"custom_dashboard_reporting_module"},{"key":"support_inventory","label":"Inventory or production tracking.","signals":["inventory"],"addonKey":"inventory_production_module"},{"key":"support_integration","label":"Third-party integration.","signals":["integration"],"addonKey":"standard_third_party_integration"},{"key":"support_migration","label":"Data/content migration.","signals":["migration"],"addonKey":"content_data_migration"},{"key":"support_client_assets","label":"I will provide final copy, images, and brand assets.","signals":["no_system_effect"]}],"selection":"multiple","scope":"universal","helpText":"Select all that apply.","required":true}]$json$::jsonb),
  ('service_businesses', $json$[{"key":"q1_goal","prompt":"What result matters most right now?","options":[{"key":"service_goal_qualified_inquiries","label":"Receive more qualified inquiries.","signals":["lead_generation"]},{"key":"service_goal_book_appointments","label":"Book more appointments or consultations.","signals":["booking","lead_generation"]},{"key":"service_goal_reduce_no_shows","label":"Reduce no-shows and repetitive follow-up.","signals":["follow_up","booking"]},{"key":"service_goal_organize_delivery","label":"Organize client intake and service delivery.","signals":["onboarding","pipeline","dashboard"]}],"selection":"single","scope":"audience","required":true},{"key":"q2_setup","prompt":"How do clients currently contact or book you?","options":[{"key":"service_setup_social_calls_dm","label":"Social media, calls, or direct messages.","signals":["lead_generation"]},{"key":"service_setup_basic_website_manual","label":"A basic website and manual follow-up.","signals":["credibility","follow_up"]},{"key":"service_setup_disconnected_booking","label":"A booking tool that is not connected to the rest of the workflow.","signals":["booking","disconnected_tools"]},{"key":"service_setup_tools_spreadsheets","label":"Several tools and spreadsheets that do not work together.","signals":["disconnected_tools","pipeline"]}],"selection":"single","scope":"audience","required":true},{"key":"q3_blocker","prompt":"Where does the process usually break down?","options":[{"key":"service_blocker_unclear_offer","label":"Visitors do not understand the offer.","signals":["credibility","lead_generation"]},{"key":"service_blocker_inquiries_no_booking","label":"Inquiries do not consistently become bookings.","signals":["booking","lead_generation"]},{"key":"service_blocker_manual_intake_follow_up","label":"Intake, reminders, and follow-up take too much time.","signals":["follow_up","onboarding"]},{"key":"service_blocker_tracking_status","label":"Client information and project status are difficult to track.","signals":["pipeline","dashboard"]}],"selection":"single","scope":"audience","required":true},{"key":"q4_capabilities","prompt":"What should the new system handle?","options":[{"key":"service_capability_website","label":"Professional service website.","signals":["credibility"]},{"key":"service_capability_qualification","label":"Lead qualification form.","signals":["lead_generation","pipeline"]},{"key":"service_capability_booking","label":"Appointment booking.","signals":["booking"]},{"key":"service_capability_reminders","label":"Automated reminders and follow-up.","signals":["follow_up"]},{"key":"service_capability_onboarding","label":"Client intake and onboarding.","signals":["onboarding"]},{"key":"service_capability_crm","label":"CRM pipeline.","signals":["pipeline"]},{"key":"service_capability_portal_dashboard","label":"Client portal or dashboard.","signals":["portal","dashboard"]}],"selection":"multiple","scope":"audience","helpText":"Select all that apply.","required":true},{"key":"q5_complexity","prompt":"How complex is your service workflow?","options":[{"key":"service_complexity_one_service","label":"One service and a simple booking flow.","signals":["simple_scope","booking"]},{"key":"service_complexity_multiple_services","label":"Several services, locations, or team members.","signals":["multiple_offers","pipeline"]},{"key":"service_complexity_multistep_approval","label":"Multi-step intake, approval, or onboarding.","signals":["onboarding","approvals"]},{"key":"service_complexity_custom_operations","label":"Custom operations, permissions, or integrations.","signals":["multiple_roles","integration"]}],"selection":"single","scope":"audience","required":true},{"key":"q6_readiness","prompt":"When do you want to begin?","options":[{"key":"readiness_ready_now","label":"Ready now.","signals":[],"readiness":"ready_now"},{"key":"readiness_within_30_days","label":"Within 30 days.","signals":[],"readiness":"within_30_days"},{"key":"readiness_within_1_2_months","label":"Within 1–2 months.","signals":[],"readiness":"planning_1_2_months"},{"key":"readiness_researching","label":"Researching for later.","signals":[],"readiness":"researching"}],"selection":"single","scope":"universal","required":true},{"key":"q7_platform","prompt":"Do you already have a preferred platform?","options":[{"key":"platform_systeme","label":"Systeme.io.","signals":[],"platformPreference":"systeme_io"},{"key":"platform_gohighlevel","label":"GoHighLevel.","signals":[],"platformPreference":"gohighlevel"},{"key":"platform_custom_app","label":"I want a custom-built app.","signals":[],"platformPreference":"custom_app"},{"key":"platform_recommend","label":"I am not sure—recommend the best fit for me.","signals":[]}],"selection":"single","scope":"universal","required":true},{"key":"q8_support","prompt":"What additional support do you need for this project?","options":[{"key":"support_conversion_copywriting","label":"Conversion copywriting.","signals":["no_system_effect"],"addonKey":"conversion_copywriting"},{"key":"support_image_sourcing","label":"Image sourcing and selection.","signals":["no_system_effect"],"addonKey":"image_sourcing_selection"},{"key":"support_image_editing","label":"Image editing and optimization.","signals":["no_system_effect"],"addonKey":"image_editing_optimization"},{"key":"support_brand_direction","label":"Brand styling or mini visual direction.","signals":["no_system_effect"],"addonKey":"mini_brand_direction"},{"key":"support_additional_pages","label":"Additional pages or funnel steps.","signals":["credibility"],"addonKey":"additional_page_step"},{"key":"support_booking","label":"Appointment booking setup.","signals":["booking"],"addonKey":"advanced_booking_setup"},{"key":"support_checkout","label":"Checkout or payment integration.","signals":["checkout"],"addonKey":"checkout_payment_integration"},{"key":"support_follow_up","label":"Email or SMS follow-up automation.","signals":["follow_up"],"addonKey":"additional_email_automation"},{"key":"support_crm","label":"CRM or pipeline setup.","signals":["pipeline"],"addonKey":"additional_crm_pipeline"},{"key":"support_onboarding","label":"Client/student onboarding.","signals":["onboarding"],"addonKey":"advanced_onboarding_workflow"},{"key":"support_portal","label":"Client/student portal.","signals":["portal"]},{"key":"support_order_management","label":"Order-management workflow.","signals":["custom_orders","order_tracking"],"addonKey":"custom_order_management_module"},{"key":"support_dashboard","label":"Dashboard or reporting.","signals":["dashboard"],"addonKey":"custom_dashboard_reporting_module"},{"key":"support_inventory","label":"Inventory or production tracking.","signals":["inventory"],"addonKey":"inventory_production_module"},{"key":"support_integration","label":"Third-party integration.","signals":["integration"],"addonKey":"standard_third_party_integration"},{"key":"support_migration","label":"Data/content migration.","signals":["migration"],"addonKey":"content_data_migration"},{"key":"support_client_assets","label":"I will provide final copy, images, and brand assets.","signals":["no_system_effect"]}],"selection":"multiple","scope":"universal","helpText":"Select all that apply.","required":true}]$json$::jsonb),
