insert into public.quiz_definitions (audience_key, version, active, questions, scoring_rules)
select d.audience_key, 1, true, d.questions, r.scoring_rules
from approved_quiz_definitions d cross join approved_rules r
on conflict (audience_key, version) do update
set questions = excluded.questions,
    scoring_rules = excluded.scoring_rules,
    active = excluded.active,
    updated_at = now();

